//! Rendering type definitions to source text.
//!
//! One file per module; every file opens with the `@generated` banner. Types
//! reference each other by `super::<module>::<Name>` paths, so no module
//! re-exports anything.

use std::collections::BTreeSet;
use std::fmt::{self, Write};

use crate::lower::{
    Cardinality, Docs, Field, PRIMITIVES_MODULE, RESOURCE_MODULE, Scalar, Target, TypeDef,
    TypeKind, UNKNOWN_RESOURCE, Variant, VersionModule,
};
use crate::naming::module_name;

/// The banner every generated file starts with.
#[must_use]
pub fn banner(model: &VersionModule) -> String {
    format!(
        "// @generated by fhir-codegen from {} {}. DO NOT EDIT.\n// Change the emitter (tools/fhir-codegen) and regenerate.\n",
        model.package_name, model.package_version
    )
}

/// The banner of a file that belongs to every version, naming every package.
#[must_use]
pub fn crate_banner(models: &[VersionModule]) -> String {
    let packages: Vec<String> = models
        .iter()
        .map(|model| format!("{} {}", model.package_name, model.package_version))
        .collect();
    format!(
        "// @generated by fhir-codegen from {}. DO NOT EDIT.\n// Change the emitter (tools/fhir-codegen) and regenerate.\n",
        packages.join(", ")
    )
}

/// The `src/lib.rs` of the generated crate, declaring every version module.
///
/// # Errors
///
/// Returns [`fmt::Error`] only if writing to the string fails, which `String` never does.
pub fn render_lib(models: &[VersionModule]) -> Result<String, fmt::Error> {
    let mut out = crate_banner(models);
    out.push_str(
        "//! Per-version FHIR types and terminology operation contracts.\n//!\n//! Generated by `fhir-codegen` from the vendored HL7 FHIR packages, one\n//! module per FHIR version. Every file is `@generated`; change the emitter\n//! and regenerate, never the output.\n",
    );
    out.push_str("#![allow(\n    clippy::doc_markdown,\n    clippy::large_enum_variant,\n    clippy::module_name_repetitions,\n    clippy::struct_field_names,\n    clippy::too_many_lines,\n    clippy::similar_names,\n    clippy::map_err_ignore,\n    unused_qualifications,\n    reason = \"generated from the FHIR specification: the documentation is the specification's own text, choice enums hold every allowed type, modules mirror FHIR type names, the codec of a large resource is one long function over FHIR-named locals, a primitive that fails to parse is reported by its path and kind, and every path is spelled from the crate root by construction\"\n)]\n\n");
    writeln!(out, "pub mod codec;")?;
    writeln!(out, "pub mod operation;")?;
    writeln!(out, "pub mod xml;")?;
    for model in models {
        writeln!(out, "pub mod {};", model.name)?;
    }
    Ok(out)
}

/// The `mod.rs` of the version module.
///
/// # Errors
///
/// Returns [`fmt::Error`] only if writing to the string fails, which `String` never does.
pub fn render_version_mod(model: &VersionModule) -> Result<String, fmt::Error> {
    let mut out = banner(model);
    writeln!(
        out,
        "//! FHIR {} types: the terminology root set and the complete closure of the\n//! datatypes and primitives it references, from `{}` {}.\n",
        model.name.to_uppercase(),
        model.package_name,
        model.package_version
    )?;
    for module in model.modules().keys() {
        writeln!(out, "pub mod {module};")?;
    }
    writeln!(out, "pub mod operations;")?;
    writeln!(out, "pub mod schema;")?;
    Ok(out)
}

/// One module file.
///
/// # Errors
///
/// Returns [`fmt::Error`] only if writing to the string fails, which `String` never does.
pub fn render_module(
    model: &VersionModule,
    module: &str,
    types: &[&TypeDef],
) -> Result<String, fmt::Error> {
    let mut out = banner(model);
    let heading = match module {
        PRIMITIVES_MODULE => format!(
            "The FHIR primitive types (<https://hl7.org/fhir/{}/datatypes.html#primitive>).",
            model.name.to_uppercase()
        ),
        RESOURCE_MODULE => {
            String::from("The abstract `Resource` type as an enum over the root set.")
        }
        _ => types
            .iter()
            .find(|ty| module_name(&ty.name) == module)
            .and_then(|ty| ty.docs.short.clone())
            .map_or_else(
                || format!("The `{module}` type and its parts."),
                |short| escape_doc(&short),
            ),
    };
    writeln!(out, "//! {heading}\n")?;
    let defaultable = defaultable(model);
    for ty in types {
        render_type(model, &mut out, module, ty, &defaultable)?;
        crate::render_codec::render_codec(model, &mut out, ty)?;
        out.push('\n');
    }
    Ok(out)
}

/// The types that derive `Default`, as a fixpoint.
///
/// A struct qualifies when every required element is a scalar or a defaultable
/// type. A choice enum and the resource enum never do, so a struct with a
/// required choice element is built explicitly. No FHIR spec governs the Rust
/// surface: our own design.
#[must_use]
pub fn defaultable(model: &VersionModule) -> BTreeSet<String> {
    let mut set: BTreeSet<String> = model
        .types
        .values()
        .filter(|ty| matches!(ty.kind, TypeKind::UnknownResource))
        .map(|ty| ty.name.clone())
        .collect();
    loop {
        let before = set.len();
        for ty in model.types.values() {
            if set.contains(&ty.name) {
                continue;
            }
            if let TypeKind::Struct { fields } = &ty.kind
                && fields.iter().all(|field| keeps_default(field, &set))
            {
                set.insert(ty.name.clone());
            }
        }
        if set.len() == before {
            return set;
        }
    }
}

/// Whether `field` leaves a `Default` derive intact, given the qualifying `set`.
fn keeps_default(field: &Field, set: &BTreeSet<String>) -> bool {
    if field.ty.card != Cardinality::One {
        return true;
    }
    match &field.ty.target {
        Target::Inline(_) => true,
        Target::Named(name) => set.contains(name),
    }
}

fn render_type(
    model: &VersionModule,
    out: &mut String,
    module: &str,
    ty: &TypeDef,
    defaultable: &BTreeSet<String>,
) -> fmt::Result {
    render_docs(out, &ty.docs, "")?;
    match &ty.kind {
        TypeKind::Struct { fields } => {
            if defaultable.contains(&ty.name) {
                out.push_str("#[derive(Debug, Clone, Default, PartialEq, Eq)]\n");
            } else {
                out.push_str("#[derive(Debug, Clone, PartialEq, Eq)]\n");
            }
            writeln!(out, "pub struct {} {{", ty.name)?;
            for field in fields {
                render_field(model, out, module, field)?;
            }
            out.push_str("}\n");
            if ty.is_primitive && defaultable.contains(&ty.name) {
                render_value_constructors(out, ty, fields)?;
            }
        }
        TypeKind::Choice { variants, .. } => {
            out.push_str("#[derive(Debug, Clone, PartialEq, Eq)]\n");
            writeln!(out, "pub enum {} {{", ty.name)?;
            for variant in variants {
                render_variant(model, out, module, variant)?;
            }
            out.push_str("}\n");
        }
        TypeKind::ResourceEnum { resources } => {
            out.push_str("#[derive(Debug, Clone, PartialEq, Eq)]\n");
            writeln!(out, "pub enum {} {{", ty.name)?;
            for resource in resources {
                writeln!(out, "    /// A `{resource}` resource.")?;
                writeln!(
                    out,
                    "    {resource}(Box<super::{}::{resource}>),",
                    module_name(resource)
                )?;
            }
            out.push_str("    /// A resource of a type outside the root set.\n");
            writeln!(out, "    Unknown({UNKNOWN_RESOURCE}),")?;
            out.push_str("}\n");
        }
        TypeKind::UnknownResource => {
            out.push_str("#[derive(Debug, Clone, Default, PartialEq, Eq)]\n");
            writeln!(out, "pub struct {} {{", ty.name)?;
            out.push_str("    /// The `resourceType` of the carried resource.\n");
            out.push_str("    pub resource_type: std::string::String,\n");
            out.push_str("    /// The complete JSON object, `resourceType` included.\n");
            out.push_str("    pub body: serde_json::Value,\n");
            out.push_str("}\n");
        }
    }
    Ok(())
}

/// `From<value>` for a primitive: the string-valued ones from both `&str` and
/// `String`, the others from their scalar (C-CONV).
fn render_value_constructors(out: &mut String, ty: &TypeDef, fields: &[Field]) -> fmt::Result {
    let Some(value) = fields.iter().find(|field| field.name == "value") else {
        return Ok(());
    };
    let Target::Inline(scalar) = &value.ty.target else {
        return Ok(());
    };
    let scalar_type = match scalar {
        Scalar::Bool => "bool",
        Scalar::I32 => "i32",
        Scalar::U32 => "u32",
        Scalar::I64 => "i64",
        Scalar::Str => "std::string::String",
    };
    let stored = match value.ty.card {
        Cardinality::One => "value",
        Cardinality::Optional => "value: Some(value)",
        Cardinality::Many => return Ok(()),
    };
    writeln!(out, "impl From<{scalar_type}> for {} {{", ty.name)?;
    writeln!(out, "    fn from(value: {scalar_type}) -> Self {{")?;
    if fields.len() == 1 {
        writeln!(out, "        Self {{ {stored} }}")?;
    } else {
        writeln!(out, "        Self {{ {stored}, ..Self::default() }}")?;
    }
    out.push_str("    }\n}\n");
    if *scalar == Scalar::Str {
        writeln!(out, "impl From<&str> for {} {{", ty.name)?;
        out.push_str("    fn from(value: &str) -> Self {\n");
        out.push_str("        Self::from(std::string::String::from(value))\n");
        out.push_str("    }\n}\n");
    }
    Ok(())
}

fn render_field(
    model: &VersionModule,
    out: &mut String,
    module: &str,
    field: &Field,
) -> fmt::Result {
    render_docs(out, &field.docs, "    ")?;
    let inner = render_target(model, module, &field.ty.target, field.ty.boxed);
    let ty = match field.ty.card {
        Cardinality::One => inner,
        Cardinality::Optional => format!("Option<{inner}>"),
        Cardinality::Many => format!("Vec<{inner}>"),
    };
    writeln!(out, "    pub {}: {ty},", field.name)
}

fn render_variant(
    model: &VersionModule,
    out: &mut String,
    module: &str,
    variant: &Variant,
) -> fmt::Result {
    writeln!(out, "    /// The `{}` form.", variant.code)?;
    let inner = render_target(model, module, &variant.target, variant.boxed);
    writeln!(out, "    {}({inner}),", variant.name)
}

fn render_target(model: &VersionModule, module: &str, target: &Target, boxed: bool) -> String {
    let path = match target {
        Target::Inline(Scalar::Bool) => String::from("bool"),
        Target::Inline(Scalar::I32) => String::from("i32"),
        Target::Inline(Scalar::U32) => String::from("u32"),
        Target::Inline(Scalar::I64) => String::from("i64"),
        Target::Inline(Scalar::Str) => String::from("std::string::String"),
        Target::Named(name) => {
            let target_module = model
                .types
                .get(name)
                .map_or_else(|| module_name(name), |ty| ty.module.clone());
            if target_module == module {
                name.clone()
            } else {
                format!("super::{target_module}::{name}")
            }
        }
    };
    if boxed { format!("Box<{path}>") } else { path }
}

fn render_docs(out: &mut String, docs: &Docs, indent: &str) -> fmt::Result {
    let short = docs.short.as_deref().map(escape_doc);
    let definition = docs.definition.as_deref().map(escape_doc);
    match (short, definition) {
        (Some(short), Some(definition)) if same_sentence(&short, &definition) => {
            for line in wrap(&definition) {
                writeln!(out, "{indent}/// {line}")?;
            }
        }
        (Some(short), Some(definition)) => {
            for line in wrap(&short) {
                writeln!(out, "{indent}/// {line}")?;
            }
            writeln!(out, "{indent}///")?;
            for line in wrap(&definition) {
                writeln!(out, "{indent}/// {line}")?;
            }
        }
        (Some(text), None) | (None, Some(text)) => {
            for line in wrap(&text) {
                writeln!(out, "{indent}/// {line}")?;
            }
        }
        (None, None) => {
            writeln!(out, "{indent}/// (undocumented in the package)")?;
        }
    }
    Ok(())
}

/// Whether the short description and the definition say the same thing, so the
/// documentation shows the sentence once.
fn same_sentence(short: &str, definition: &str) -> bool {
    let trim = |s: &str| s.trim_end_matches(['.', '!']).trim().to_lowercase();
    trim(short) == trim(definition)
}

/// Escapes specification text for rustdoc.
///
/// Brackets would read as intra-doc links, angle brackets and asterisks as
/// markup, and a bare URL fails the `bare_urls` lint, so every URL is wrapped
/// in angle brackets wherever it sits in the text.
#[must_use]
pub fn escape_doc(text: &str) -> String {
    let chars: Vec<char> = text
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .chars()
        .collect();
    let mut out = String::with_capacity(chars.len() + 16);
    let mut index = 0;
    while index < chars.len() {
        if starts_url(&chars, index) {
            let start = index;
            let (end, next) = url_span(&chars, start);
            index = next;
            out.push('<');
            out.extend(chars.get(start..end).into_iter().flatten());
            out.push('>');
            out.extend(chars.get(end..index).into_iter().flatten());
        } else if let Some(ch) = chars.get(index) {
            escape_char(&mut out, *ch);
            index += 1;
        }
    }
    out
}

/// The URL that starts at `start`: where its text ends, and where the prose
/// resumes.
///
/// The two positions differ when the URL closes a sentence, because trailing
/// punctuation stays outside the angle brackets.
fn url_span(chars: &[char], start: usize) -> (usize, usize) {
    let mut next = start;
    while next < chars.len() && !chars.get(next).copied().is_some_and(ends_url) {
        next += 1;
    }
    let mut end = next;
    while end > start
        && chars
            .get(end - 1)
            .copied()
            .is_some_and(|c| matches!(c, '.' | ',' | ';' | ':'))
    {
        end -= 1;
    }
    (end, next)
}

/// Whether `c` closes a URL in specification prose.
fn ends_url(c: char) -> bool {
    c.is_whitespace() || matches!(c, ')' | ']' | '`' | '\\' | '<' | '>' | '"' | '\'')
}

/// Writes `ch`, backslash-escaped where rustdoc would read it as markup.
fn escape_char(out: &mut String, ch: char) {
    if matches!(ch, '[' | ']' | '<' | '>' | '*' | '_' | '`' | '\\' | '#') {
        out.push('\\');
    }
    out.push(ch);
}

fn starts_url(chars: &[char], index: usize) -> bool {
    const HTTP: [char; 7] = ['h', 't', 't', 'p', ':', '/', '/'];
    const HTTPS: [char; 8] = ['h', 't', 't', 'p', 's', ':', '/', '/'];
    chars.get(index..index + HTTP.len()) == Some(&HTTP[..])
        || chars.get(index..index + HTTPS.len()) == Some(&HTTPS[..])
}

fn wrap(text: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let mut current = String::new();
    for word in text.split(' ') {
        if !current.is_empty() && current.chars().count() + 1 + word.chars().count() > 76 {
            lines.push(std::mem::take(&mut current));
        }
        if !current.is_empty() {
            current.push(' ');
        }
        current.push_str(word);
    }
    if !current.is_empty() {
        lines.push(current);
    }
    lines
}

#[cfg(test)]
mod tests {
    use super::escape_doc;

    #[test]
    fn identical_short_and_definition_render_once() {
        let mut out = String::new();
        super::render_docs(
            &mut out,
            &crate::lower::Docs {
                short: Some("ISO 4217 Currency Code".to_owned()),
                definition: Some("ISO 4217 Currency Code.".to_owned()),
            },
            "",
        )
        .expect("renders");
        assert_eq!(out, "/// ISO 4217 Currency Code.\n");
    }

    #[test]
    fn brackets_and_urls_are_escaped() {
        assert_eq!(escape_doc("The value[x] of it"), "The value\\[x\\] of it");
        assert_eq!(
            escape_doc("See http://hl7.org/fhir. Now"),
            "See <http://hl7.org/fhir>. Now"
        );
        assert_eq!(escape_doc("a <b> c"), "a \\<b\\> c");
        assert_eq!(
            escape_doc("[link](http://x.org/a#b) done"),
            "\\[link\\](<http://x.org/a#b>) done"
        );
        assert_eq!(
            escape_doc("```http://x.org```), that"),
            "\\`\\`\\`<http://x.org>\\`\\`\\`), that"
        );
    }
}
